// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.SocialFlow.CreateBulk(builders...).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.SocialFlowUpsert) {
//			SetPurpose(v+v).
//		}).
//		Exec(ctx)
func (_c *SocialFlowCreateBulk) OnConflict(opts ...sql.ConflictOption) *SocialFlowUpsertBulk {
	_c.conflict = opts
	return &SocialFlowUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.SocialFlow.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *SocialFlowCreateBulk) OnConflictColumns(columns ...string) *SocialFlowUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &SocialFlowUpsertBulk{
		create: _c,
	}
}

// SocialFlowUpsertBulk is the builder for "upsert"-ing
// a bulk of SocialFlow nodes.
type SocialFlowUpsertBulk struct {
	create *SocialFlowCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.SocialFlow.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(socialflow.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *SocialFlowUpsertBulk) UpdateNewValues() *SocialFlowUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(socialflow.FieldID)
			}
			if _, exists := b.mutation.Purpose(); exists {
				s.SetIgnore(socialflow.FieldPurpose)
			}
			if _, exists := b.mutation.Provider(); exists {
				s.SetIgnore(socialflow.FieldProvider)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(socialflow.FieldUserID)
			}
			if _, exists := b.mutation.Verifier(); exists {
				s.SetIgnore(socialflow.FieldVerifier)
			}
			if _, exists := b.mutation.Nonce(); exists {
				s.SetIgnore(socialflow.FieldNonce)
			}
			if _, exists := b.mutation.Next(); exists {
				s.SetIgnore(socialflow.FieldNext)
			}
			if _, exists := b.mutation.Remember(); exists {
				s.SetIgnore(socialflow.FieldRemember)
			}
			if _, exists := b.mutation.Subject(); exists {
				s.SetIgnore(socialflow.FieldSubject)
			}
			if _, exists := b.mutation.Email(); exists {
				s.SetIgnore(socialflow.FieldEmail)
			}
			if _, exists := b.mutation.EmailVerified(); exists {
				s.SetIgnore(socialflow.FieldEmailVerified)
			}
			if _, exists := b.mutation.Name(); exists {
				s.SetIgnore(socialflow.FieldName)
			}
			if _, exists := b.mutation.Nickname(); exists {
				s.SetIgnore(socialflow.FieldNickname)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(socialflow.FieldCreatedAt)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(socialflow.FieldExpiresAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.SocialFlow.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *SocialFlowUpsertBulk) Ignore() *SocialFlowUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *SocialFlowUpsertBulk) DoNothing() *SocialFlowUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the SocialFlowCreateBulk.OnConflict
// documentation for more info.
func (u *SocialFlowUpsertBulk) Update(set func(*SocialFlowUpsert)) *SocialFlowUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&SocialFlowUpsert{UpdateSet: update})
	}))
	return u
}

// Exec executes the query.
func (u *SocialFlowUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the SocialFlowCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for SocialFlowCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *SocialFlowUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
